<script setup lang="ts">
import { Head, router } from '@inertiajs/vue3'
import { ref } from 'vue'
defineProps<{result:{rooms?:any[];total_rooms?:number};filters:Record<string,any>;error:string|null}>()
const search=ref(''),order=ref('joined_members'),loading=ref(false)
const apply=()=>{loading.value=true;router.get('/rooms',{search_term:search.value,order_by:order.value,from:0,limit:50},{preserveState:true,onFinish:()=>loading.value=false})}
</script>
<template><Head title="مدیریت اتاق‌ها"/><v-container fluid class="pa-6"><div class="d-flex justify-space-between align-center mb-5"><h1 class="text-h4">اتاق‌ها</h1><v-btn color="primary" @click="apply">به‌روزرسانی</v-btn></div><v-card rounded="xl" class="pa-4"><v-row><v-col cols="12" md="6"><v-text-field v-model="search" label="جستجوی نام، شناسه یا alias" prepend-inner-icon="mdi-magnify" hide-details @keyup.enter="apply"/></v-col><v-col cols="12" md="3"><v-select v-model="order" label="مرتب‌سازی" :items="[{title:'تعداد اعضا',value:'joined_members'},{title:'نام',value:'name'}]" hide-details/></v-col><v-col cols="12" md="3"><v-btn block color="primary" @click="apply">جستجو</v-btn></v-col></v-row><v-alert v-if="error" type="error" variant="tonal">{{ error }}</v-alert><v-skeleton-loader v-if="loading" type="table-row@8"/><v-row v-else class="mt-2"><v-col v-for="room in (result.rooms||[])" :key="room.room_id" cols="12" md="6" lg="4"><v-card rounded="lg" variant="tonal" class="pa-3 h-100"><v-card-title class="text-subtitle-1">{{ room.name||'بدون نام' }}</v-card-title><v-card-subtitle>{{ room.room_id }}</v-card-subtitle><v-card-text><v-chip size="small">{{ room.joined_members??0 }} عضو</v-chip><div class="text-caption mt-2">اندازه: {{ room.size??'—' }}</div></v-card-text><v-card-actions><v-btn variant="text" :href="'/rooms/'+encodeURIComponent(room.room_id)">جزئیات اتاق</v-btn></v-card-actions></v-card></v-col></v-row><div class="text-caption mt-3">تعداد اتاق‌ها: {{ result.total_rooms??0 }}</div></v-card></v-container></template>
